package glitch

import data.glitch_lib

# Primary suspicious markers (high confidence)
task_indicators := {"TODO", "FIXME", "XXX", "HACK", "BUG", "TEMP", "TEMPORARY"}
temporal_deferrals := {"LATER", "NEXT VERSION", "POST-DEPLOY", "FUTURE", "WIP", "PENDING"}
security_specific := {"INSECURE", "DISABLED FOR NOW", "BYPASS", "WORKAROUND", "DEBUG ONLY", "TEST ONLY", "DO NOT USE IN PROD"}

# Contextual risk amplifiers
risk_amplifiers := {"disable verification", "skip check", "remove before", "placeholder certificate", "hardcoded", "default password", "change this", "replace me", "handle error", "error TBD", "exception ignored"}

all_suspicious_patterns := {p | p := task_indicators[_]} | {p | p := temporal_deferrals[_]} | {p | p := security_specific[_]} | {p | p := risk_amplifiers[_]}

contains_suspicious_pattern(content) {
    lower := lower(content)
    some pattern in all_suspicious_patterns
    contains(lower, lower(pattern))
}

# Collect all comments from a UnitBlock
all_comments(node) = comments {
    comments := {n |
        walk(node, [path, n])
        n.ir_type == "Comment"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check direct comments in UnitBlock
    comment := parent.comments[_]
    contains_suspicious_pattern(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment indicating incomplete security implementation - Comments containing TODO, FIXME, HACK, or security-related temporary markers may indicate known deficiencies. (CWE-546)"
